// Log de error createSubscriber
// El IF anterior nos manda acá si status != 'success'
// Capturamos detalles para debugging sin romper el batch

const lead = $('Split In Batches (1)').item.json;
const manychatResponse = $input.first().json;

const error = {
  timestamp: new Date().toISOString(),
  lead_id: lead.id_2,
  telefono: lead.Telefono,
  nombre: lead.Nombre,
  manychat_status: manychatResponse.status || 'unknown',
  manychat_message: manychatResponse.message || 'No message',
  manychat_details: manychatResponse.details || manychatResponse,
};

console.log('[outreach-form-meta] createSubscriber FAIL:', JSON.stringify(error, null, 2));

// Retorna el error para que un siguiente nodo lo pueda loguear a Airtable / Slack / Telegram si se quiere
return [{ json: error }];
